                        employee_id: Trim(txtEmpFId.Text), full_name: Trim(txtEmpFName.Text), department_name: Trim(txtEmpFDept.Text), email: Trim(txtEmpFMail.Text)
                    }),
                    "employeeInsert"
                ),
                Blank()
            )
        },
        If(
            IsBlank(apiResult),
            Set(varNotifyErrorMessage, "Power Automate のフローに接続できません");
            Set(varShowNotifyFailed, true),
            !IsBlank(Trim(Coalesce(Text(apiResult.error), ""))),
            Set(varNotifyErrorMessage, Text(apiResult.error));
            Set(varShowNotifyFailed, true),
            IsBlank(apiResult.response) || Left(apiResult.response, 8) = "{""error""",
            Set(varNotifyErrorMessage, IfError(Text(ParseJSON(apiResult.response).error), "社員の登録に失敗しました"));
            Set(varShowNotifyFailed, true),
            Set(varEmpSuccessTitle, "登録しました");
            Set(varEmpSuccessMessage, "新しい従業員を追加しました。");
            Set(varShowNotifyFailed, false);
            Set(varShowEmpInsertSuccess, true);
            Set(varShowEmpModal, false);
            Set(gblPage, 1);
            Set(varEmpRaw, IfError(With({apiResult: 'EDS-APIManagement1'.Run("employee", "{""page"":" & gblPage & ",""pageSize"":" & gblPageSize & If(IsBlank(varEmpSearch), "", ",""search_keyword"":" & JSON(varEmpSearch)) & "}", "employeeList")}, If(!IsBlank(Trim(Coalesce(Text(apiResult.error), ""))), Set(varNotifyErrorMessage, Text(apiResult.error)); Set(varShowNotifyFailed, true); "", Set(varShowNotifyFailed, false); Substitute(apiResult.response, ":null", ":"""""))), Set(varNotifyErrorMessage, "Power Automate のフローに接続できません"); Set(varShowNotifyFailed, true); ""));
